import { Component, inject } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import {
  MAT_DIALOG_DATA,
  MatDialog,
  MatDialogModule,
  MatDialogRef,
} from '@angular/material/dialog';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';

interface EditItemData {
  name: string;
}

@Component({
  selector: 'app-edit-item-dialog',
  standalone: true,
  imports: [MatDialogModule, MatFormFieldModule, MatInputModule, MatButtonModule, ReactiveFormsModule],
  templateUrl: './edit-item-dialog.component.html',
})
export class EditItemDialogComponent {
  dialogRef = inject(MatDialogRef<EditItemDialogComponent, EditItemData>);
  private data = inject<EditItemData>(MAT_DIALOG_DATA);
  private fb = inject(FormBuilder);

  form = this.fb.group({
    name: [this.data.name, Validators.required],
  });

  save(): void {
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      return;
    }
    this.dialogRef.close({ name: this.form.value.name! });
  }
}

@Component({
  selector: 'app-example',
  standalone: true,
  imports: [MatButtonModule],
  template: `<button mat-button (click)="openEditDialog()">Edit</button>`,
})
export class ExampleComponent {
  private dialog = inject(MatDialog);

  openEditDialog(): void {
    const ref = this.dialog.open(EditItemDialogComponent, { data: { name: 'Widget' } });
    ref.afterClosed().subscribe((result: EditItemData | undefined) => {
      if (result) {
        console.log('saved', result);
      }
    });
  }
}
